"""Kaggle entry for Table 1.

Generated from the repo files. Unpacks those exact sources and runs
scripts/table1.py. The checks are not reimplemented here.
GPU stays off: this script never requests an accelerator.
"""

from __future__ import annotations

import base64
import json
import os
import runpy
import sys
import tempfile
from pathlib import Path

PAYLOAD = json.loads(r"""
{
  "src/dl4stg/__init__.py": "IiIiREw0U1RHIEFzc2lnbm1lbnQgMiBwYWNrYWdlLiIiIgo=",
  "src/dl4stg/transforms.py": "",
  "src/dl4stg/windows.py": "",
  "src/dl4stg/data.py": "",
  "src/dl4stg/metrics.py": "",
  "scripts/table1.py": ""
}
""")


def main() -> None:
    dest = Path(tempfile.mkdtemp(prefix="dl4stg_table1_"))
    for rel, b64 in PAYLOAD.items():
        path = dest / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(base64.b64decode(b64))
    working = Path("/kaggle/working")
    if working.is_dir():
        os.chdir(working)
    script = dest / "scripts" / "table1.py"
    sys.path.insert(0, str(dest / "src"))
    runpy.run_path(str(script), run_name="__main__")


if __name__ == "__main__":
    main()
